    lp=np.concatenate([np.log(lam)+rp, np.log1p(-lam)+lpi[isz]])
    P=np.zeros((len(uniq),100))
    for i,ss in enumerate(subs):
        for s in ss:
            lj=EL[:,np.array(s)-1].sum(1)+lp; post=np.exp(lj-logsumexp(lj)); P[i]+=post@M/len(ss)
